# ---- b042+ : references for the remaining prompts, using the extended tool set
def t(tool, **k): return {"tool": tool, **k}
def mat(name, color, **k): return t("set_material", name=name, color=color, **k)
def light(kind, **k): return t("add_light", kind=kind, **k)
def kf(obj, prop, frame, **k): return t("keyframe", **({"object": obj} if obj else {}), property=prop, frame=frame, **k)
def box(loc, sc, **k): return p("cube", location=list(loc), scale=list(sc), **k)
def col(name, objs): return t("new_collection", name=name, objects=objs)
def par(c, pa): return t("parent", child=c, parent=pa)
